package com.shengyu.framework.netty.config;import lombok.Data;import org.springframework.boot.context.properties.ConfigurationProperties;import org.springframework.validation.annotation.Validated;import javax.validation.constraints.NotEmpty;import javax.validation.constraints.NotNull;/** * netty网络通信属性 * * @author zhusy * @since 2022/11/12 */@ConfigurationProperties(prefix = "shengyu.netty")@Validated@Datapublic class NettyProperties {    /**     * 是否开启服务     */    private boolean enable = true;    @NotNull(message = "网络通讯端口号不能为空")    private Integer port;    @NotEmpty(message = "即时通讯协议不能为空")    private String imProtocol;    /**     * 建立通讯的前置url     */    private String imSocketUrl;    /**     * 主线程数（如果不设置的话，默认是CPU核数的 *2 倍）     */    private int bossThread;    /**     * 工作线程数（如果不设置的话，默认是CPU核数的 *2 倍）     */    private int workerThread;    /**     * 临时存放已经完成三次握手的请求的队列的最大长度     */    private int backLog;    /**     * 读心跳检测，规定时间内未向服务端发送读操作心跳时间，单位秒     */    private int readHeartBeatTime;    /**     * 写心跳检测，规定时间内未发生写操作心跳时间，单位秒     */    private int writerHeartBeatTime;    /**     * 读写心跳检测，单位秒     */    private int allHeartBeatTime;}